function lineKey(axis, lean) {
  return `${axis}:${lean}`;
}
function axisOfKey(key) {
  return key.slice(0, key.indexOf(":"));
}
var STARTER_TAG = "starter";
function isLineKey(value) {
  const at = value.indexOf(":");
  if (at < 0) return false;
  const lean = value.slice(at + 1);
  return TRAIT_AXES.includes(value.slice(0, at)) && (lean === "high" || lean === "low");
}
function parseLeanTag(tag2) {
  if (tag2 === STARTER_TAG) return [];
  const parts = tag2.split("+");
  if (parts.length < 1 || parts.length > 2 || !parts.every(isLineKey)) return null;
  if (parts.length === 2 && axisOfKey(parts[0]) === axisOfKey(parts[1])) return null;
  return parts;
}
