function storyNamesACategory(body) {
  const lower = body.toLowerCase();
  for (const def of getCategoryDefs()) {
    const name = def.name.toLowerCase();
    if (name.includes(" ") || name.includes("/")) {
      if (lower.includes(name)) return true;
    }
  }
  return false;
}

